struct JSICacheRegistration final {
  JSICache* owner = nullptr;
  std::weak_ptr<JSICache> cache;
};
struct JSICacheRegistry final {
  using Entries = std::unordered_map<jsi::Runtime*, JSICacheRegistration>;
  std::mutex mutex;
