};
// Process-lifetime storage avoids global destructor ordering. Individual runtime
// nodes are still removed at their owning cache's teardown.
std::atomic<JSICacheRegistry*> jsiCacheRegistryExisting{nullptr};
JSICacheRegistry& jsiCacheRegistry() {
  static auto* const registry = [] {
    auto* created = new JSICacheRegistry();
    jsiCacheRegistryExisting.store(created);
    return created;
  }();
  return *registry;
}
} // namespace

JSICacheRegistry::Entries::node_type detachRuntimeJSICache(jsi::Runtime* runtime, JSICache* owner) {
  auto* registry = jsiCacheRegistryExisting.load();
  if (registry == nullptr) return {};
  const std::scoped_lock lock(registry->mutex);
  const auto found = registry->entries.find(runtime);
  if (found == registry->entries.end() || found->second.owner != owner) return {};
  // The caller keeps this node through invalidation and destroys it after unlock.
  return registry->entries.extract(found);
}


template <typename T>
inline void destroyReferences(const std::vector<WeakReference<T>>& references) {
  for (auto& func : references) {
    BorrowingReference<T> reference = func.lock();
    if (reference) {
      // Destroy all functions that we might still have in cache, some callbacks and Promises may now become invalid.
      reference.destroy();
    }
  }
}

JSICache::~JSICache() { invalidate(); }

void JSICache::invalidate() {
  Logger::log(LogLevel::Info, TAG, "Invalidating JSICache...");
  std::unique_lock lock(_mutex);

