  destroyReferences(_objectCache);
  destroyReferences(_functionCache);
  destroyReferences(_weakObjectCache);
  destroyReferences(_propNameIDCache);
  destroyReferences(_arrayBufferCache);
  _valueCache.clear();
  _objectCache.clear();
  _functionCache.clear();
  _weakObjectCache.clear();
  _propNameIDCache.clear();
  _arrayBufferCache.clear();
}

JSICacheReference JSICache::getOrCreateCache(jsi::Runtime& runtime) {
  auto& registry = jsiCacheRegistry();
  std::weak_ptr<JSICache> weak;
  {
    const std::scoped_lock lock(registry.mutex);
    const auto found = registry.entries.find(&runtime);
    if (found != registry.entries.end()) weak = found->second.cache;
  }
  // Never acquire a per-runtime cache lock while holding a registry lock.
  if (auto strong = weak.lock()) return JSICacheReference(strong);

  // Cache doesn't exist yet.
  Logger::log(LogLevel::Info, TAG, "Creating new JSICache<T> for runtime %s..", getRuntimeId(runtime).c_str());
  // Create new cache
  std::shared_ptr<JSICache> nativeState(new JSICache(), [runtimeKey = &runtime](JSICache* cache) {
