  std::weak_ptr<JSICache> replaced;
  {
    const std::scoped_lock lock(registry.mutex);
    auto& cached = registry.entries[&runtime];
    replaced.swap(cached.cache);
    cached.owner = nativeState.get();
    cached.cache = nativeState;
  }
  try {
    // Call Object.defineProperty(global, ...) now with our cache (it internally already uses cache)
    CommonGlobals::defineGlobal(runtime, KnownGlobalPropertyName::JSI_CACHE, std::move(cache));
  } catch (...) {
    // Invalidate this failed generation before any retry can reuse its cached
    // payloads. Its JS object may remain reachable and be collected much later.
    auto registration = detachRuntimeJSICache(&runtime, nativeState.get());
    nativeState->invalidate();
    if (!registration.empty()) {
      clearRuntimePropNameIDCache(&runtime);
      clearRuntimeCommonGlobalsCache(&runtime);
      clearRuntimeDispatcherCache(&runtime);
      clearRuntimePrototypeCache(&runtime);
    }
    throw;
  }
  // Return it
  return JSICacheReference(nativeState);
}

