  auto jsiCache = JSICache::getOrCreateCache(runtime);
  auto sharedPropName = jsiCache.makeShared(std::move(propName));

  // store it in cache...
  cache.insert_or_assign(value, sharedPropName);

  // return it!
  return *sharedPropName;
}

