// Process-lifetime storage avoids global destructor ordering. Individual runtime
// nodes are still removed at their owning cache's teardown.
std::atomic<PrototypeRegistry*> prototypeRegistryExisting{nullptr};
PrototypeRegistry& prototypeRegistry() {
  static auto* const registry = [] {
    auto* created = new PrototypeRegistry();
    prototypeRegistryExisting.store(created);
    return created;
  }();
  return *registry;
}
