void clearRuntimePrototypeCache(jsi::Runtime* runtime) {
  auto* registry = prototypeRegistryExisting.load();
  if (registry == nullptr) return;
  [[maybe_unused]] auto removed = [&] {
    const std::scoped_lock lock(registry->mutex);
    return registry->entries.extract(runtime);
  }();
}

