ThreadPool::ThreadPool(const char* name, size_t initialThreadsCount, size_t maxThreadsCount)
    : _isAlive(true), _threadCount(0), _threadCountLimit(maxThreadsCount), _name(name) {
  Logger::log(LogLevel::Info, TAG, "Creating ThreadPool \"%s\" with %i initial threads (max: %i)...", name, initialThreadsCount,
              maxThreadsCount);

  std::unique_lock<std::mutex> lock(_queueMutex);
  try {
    for (size_t i = 0; i < initialThreadsCount; i++) {
      addThread(lock);
    }
  } catch (...) {
    // A failed constructor has no destructor: stop and join partial workers
    // before its condition variable, mutex and std::thread members unwind.
    _isAlive = false;
    lock.unlock();
    _condition.notify_all();
    for (std::thread& worker : _workers) {
      if (worker.joinable()) {
        worker.join();
      }
    }
    throw;
  }
}

